PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop  : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR

IF NOT EStop THEN
    Motor := FALSE;
ELSIF Stop THEN
    Motor := FALSE;
ELSIF Start THEN
    Motor := TRUE;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR CONSTANT
    LOW_LIMIT : INT := 10;
    HIGH_LIMIT : INT := 90;
END_VAR

IF Level >= HIGH_LIMIT THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= LOW_LIMIT THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    ValveOut := FALSE;
END_IF;

END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

IF OpenA_Cmd THEN
    DoorA := TRUE;
    DoorB := FALSE;
ELSIF OpenB_Cmd THEN
    DoorA := FALSE;
    DoorB := TRUE;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

IF StopPB OR (NOT GuardClosed) OR Fault THEN
    Conveyor := FALSE;
ELSIF StartPB AND GuardClosed AND (NOT Fault) THEN
    Conveyor := TRUE;
END_IF;

END_PROGRAM

