PROGRAM intersection

VAR_OUTPUT
    NS_G : BOOL;
    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
    EW_R : BOOL;
END_VAR

VAR
    State : INT;
    TmrGreen  : TON;
    TmrYellow : TON;
    TmrAllRed : TON;
END_VAR

VAR CONSTANT
    PT_GREEN  : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

NS_G := FALSE;
NS_Y := FALSE;
NS_R := TRUE;
EW_G := FALSE;
EW_Y := FALSE;
EW_R := TRUE;

TmrGreen (IN  := (State = 0) OR (State = 3),
           PT  := PT_GREEN);

TmrYellow(IN  := (State = 1) OR (State = 4),
           PT  := PT_YELLOW);

TmrAllRed(IN  := (State = 2) OR (State = 5),
           PT  := PT_ALLRED);

CASE State OF

    0:
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        IF TmrGreen.Q THEN
            State := 1;
        END_IF;

    1:
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        IF TmrYellow.Q THEN
            State := 2;
        END_IF;

    2:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        IF TmrAllRed.Q THEN
            State := 3;
        END_IF;

    3:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := FALSE;
        IF TmrGreen.Q THEN
            State := 4;
        END_IF;

    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;
        IF TmrYellow.Q THEN
            State := 5;
        END_IF;

    5:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        IF TmrAllRed.Q THEN
            State := 0;
        END_IF;

    ELSE
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        State := 0;

END_CASE;

END_PROGRAM

PROGRAM elevator
VAR_INPUT
    CallUp    : BOOL;
    CallDown  : BOOL;
    DoorClosed: BOOL;
    AtTop     : BOOL;
    AtBottom  : BOOL;
END_VAR

VAR_OUTPUT
    MotorUp   : BOOL;
    MotorDown : BOOL;
END_VAR

VAR
    State     : INT;
END_VAR

MotorUp   := FALSE;
MotorDown := FALSE;

CASE State OF

    0:
        IF CallUp AND DoorClosed AND NOT AtTop THEN
            State := 1;
        END_IF;

    1:
        IF AtTop THEN
            State := 2;
        ELSIF NOT DoorClosed THEN
            MotorUp := FALSE;
        ELSIF AtBottom THEN
            MotorUp := FALSE;
        ELSE
            IF DoorClosed AND NOT AtTop THEN
                MotorUp := TRUE;
            END_IF;
        END_IF;

    2:
        IF CallDown AND DoorClosed AND NOT AtBottom THEN
            State := 3;
        END_IF;

    3:
        IF AtBottom THEN
            State := 0;
        ELSIF NOT DoorClosed THEN
            MotorDown := FALSE;
        ELSIF AtTop THEN
            MotorDown := FALSE;
        ELSE
            IF DoorClosed AND NOT AtBottom THEN
                MotorDown := TRUE;
            END_IF;
        END_IF;

ELSE
    State := 0;

END_CASE;

IF AtTop AND State = 1 THEN
    MotorUp   := FALSE;
    MotorDown := FALSE;
    State     := 2;
END_IF;

IF AtBottom AND State = 3 THEN
    MotorUp   := FALSE;
    MotorDown := FALSE;
    State     := 0;
END_IF;

IF NOT DoorClosed THEN
    MotorUp   := FALSE;
    MotorDown := FALSE;
END_IF;

IF AtTop THEN
    MotorUp := FALSE;
END_IF;

IF AtBottom THEN
    MotorDown := FALSE;
END_IF;

IF MotorUp AND MotorDown THEN
    MotorUp   := FALSE;
    MotorDown := FALSE;
END_IF;

END_PROGRAM

PROGRAM batch_reactor

VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT;
    ReactTimer : TON;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    LIQ_MIN : INT := 10;
END_VAR

    IF NOT EStop THEN
        State := 0;
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        ReactTimer(IN := FALSE, PT := T#3s);
    ELSE
        CASE State OF
            0:
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
                ReactTimer(IN := FALSE, PT := T#3s);
                IF StartBatch THEN
                    State := 1;
                END_IF;

            1:
                DrainValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                ReactTimer(IN := FALSE, PT := T#3s);
                IF Level >= LVL_HIGH THEN
                    FillValve := FALSE;
                    State := 2;
                ELSE
                    FillValve := TRUE;
                END_IF;

            2:
                FillValve := FALSE;
                DrainValve := FALSE;
                ReactTimer(IN := FALSE, PT := T#3s);
                IF Level >= LIQ_MIN THEN
                    Heater := TRUE;
                    Agitator := TRUE;
                ELSE
                    Heater := FALSE;
                    Agitator := FALSE;
                END_IF;
                IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
                    State := 3;
                END_IF;

            3:
                FillValve := FALSE;
                DrainValve := FALSE;
                IF Level >= LIQ_MIN THEN
                    Heater := TRUE;
                    Agitator := TRUE;
                    ReactTimer(IN := TRUE, PT := T#3s);
                ELSE
                    Heater := FALSE;
                    Agitator := FALSE;
                    ReactTimer(IN := FALSE, PT := T#3s);
                END_IF;
                IF ReactTimer.Q THEN
                    ReactTimer(IN := FALSE, PT := T#3s);
                    Heater := FALSE;
                    Agitator := FALSE;
                    State := 4;
                END_IF;

            4:
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                ReactTimer(IN := FALSE, PT := T#3s);
                IF Level <= LVL_LOW THEN
                    DrainValve := FALSE;
                    State := 0;
                ELSE
                    DrainValve := TRUE;
                END_IF;

            ELSE
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
                ReactTimer(IN := FALSE, PT := T#3s);
        END_CASE;
    END_IF;

END_PROGRAM

PROGRAM garage
VAR_INPUT
    EntrySensor : BOOL;
    ExitSensor : BOOL;
    EntryReq : BOOL;
END_VAR
VAR_OUTPUT
    FullSign : BOOL;
    EntryBarrierOpen : BOOL;
END_VAR
VAR
    Count : INT;
    PrevEntry : BOOL;
    PrevExit : BOOL;
END_VAR
VAR CONSTANT
    CAP : INT := 3;
END_VAR

IF EntrySensor AND NOT PrevEntry THEN
    IF Count < CAP THEN
        Count := Count + 1;
    END_IF;
END_IF;

IF ExitSensor AND NOT PrevExit THEN
    IF Count > 0 THEN
        Count := Count - 1;
    END_IF;
END_IF;

PrevEntry := EntrySensor;
PrevExit := ExitSensor;

IF Count >= CAP THEN
    FullSign := TRUE;
ELSE
    FullSign := FALSE;
END_IF;

IF EntryReq AND NOT FullSign THEN
    EntryBarrierOpen := TRUE;
ELSE
    EntryBarrierOpen := FALSE;
END_IF;

END_PROGRAM

PROGRAM motor_delay
VAR_INPUT
    StartCmd : BOOL;
    EStop    : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    StartTimer : TON;
END_VAR

VAR CONSTANT
    PT_DELAY : TIME := T#3s;
END_VAR

IF NOT EStop THEN
    StartTimer(IN := FALSE, PT := PT_DELAY);
    Motor := FALSE;
ELSE
    StartTimer(IN := StartCmd, PT := PT_DELAY);
    IF StartTimer.Q AND StartCmd THEN
        Motor := TRUE;
    ELSE
        Motor := FALSE;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM star_delta

VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
END_VAR

VAR_OUTPUT
    MainK  : BOOL;
    StarK  : BOOL;
    DeltaK : BOOL;
END_VAR

VAR
    State    : INT;
    StarTimer : TON;
END_VAR

StarTimer(IN := (State = 1), PT := T#3s);

IF (NOT EStop) OR StopPB THEN
    State := 0;
ELSIF State = 0 THEN
    IF StartPB AND EStop THEN
        State := 1;
    END_IF;
ELSIF State = 1 THEN
    IF StarTimer.Q THEN
        State := 2;
    END_IF;
ELSIF State = 2 THEN
    State := 2;
END_IF;

MainK  := FALSE;
StarK  := FALSE;
DeltaK := FALSE;

IF State = 1 THEN
    MainK := TRUE;
    StarK := TRUE;
ELSIF State = 2 THEN
    MainK  := TRUE;
    DeltaK := TRUE;
END_IF;

END_PROGRAM

PROGRAM ped_crossing

VAR_INPUT
    PedReq : BOOL;
END_VAR

VAR_OUTPUT
    CarGreen : BOOL;
    CarYellow : BOOL;
    CarRed : BOOL;
    PedWalk : BOOL;
END_VAR

VAR
    State : INT;
    TimerGreen : TON;
    TimerYellow : TON;
    TimerWalk : TON;
END_VAR

TimerGreen(IN := (State = 0), PT := T#3s);
TimerYellow(IN := (State = 1), PT := T#2s);
TimerWalk(IN := (State = 2), PT := T#3s);

CASE State OF
    0:
        IF TimerGreen.Q AND PedReq THEN
            State := 1;
        END_IF;
    1:
        IF TimerYellow.Q THEN
            State := 2;
        END_IF;
    2:
        IF TimerWalk.Q THEN
            State := 0;
        END_IF;
END_CASE;

CarGreen  := (State = 0);
CarYellow := (State = 1);
CarRed    := (State = 2);
PedWalk   := (State = 2);

END_PROGRAM

PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
    HIGH : INT;
    LOW : INT;
END_VAR

HIGH := 90;
LOW := 10;

IF NOT EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
ELSE
    CASE State OF
        0:
            Pump := FALSE;
            Valve := FALSE;
            IF StartCycle AND (Level < HIGH) THEN
                State := 1;
            END_IF;

        1:
            IF Level >= HIGH THEN
                Pump := FALSE;
                Valve := FALSE;
                State := 2;
            ELSE
                Pump := TRUE;
                Valve := FALSE;
            END_IF;

        2:
            IF Level <= LOW THEN
                Pump := FALSE;
                Valve := FALSE;
                State := 0;
            ELSE
                Pump := FALSE;
                Valve := TRUE;
            END_IF;

    ELSE
        State := 0;
        Pump := FALSE;
        Valve := FALSE;
    END_CASE;

    IF Level >= HIGH THEN
        Pump := FALSE;
    END_IF;
    IF Level <= LOW THEN
        Valve := FALSE;
    END_IF;
    IF Pump AND Valve THEN
        Pump := FALSE;
        Valve := FALSE;
    END_IF;

END_IF;

END_PROGRAM

PROGRAM conveyor_seq
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
END_VAR

VAR
    State : INT;
    SeqTimer : TON;
    SafeToRun : BOOL;
END_VAR

SafeToRun := (NOT StopPB) AND EStop;

SeqTimer(IN := (State = 1) AND SafeToRun, PT := T#2s);

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        IF StartPB AND SafeToRun THEN
            State := 1;
        END_IF;

    1:
        C2 := TRUE;
        C1 := FALSE;
        IF NOT SafeToRun THEN
            State := 0;
        ELSIF SeqTimer.Q THEN
            State := 2;
        END_IF;

    2:
        C2 := TRUE;
        C1 := TRUE;
        IF NOT SafeToRun THEN
            State := 0;
        END_IF;

ELSE
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
END_CASE;

IF State = 0 THEN
    C1 := FALSE;
    C2 := FALSE;
END_IF;

END_PROGRAM

PROGRAM burner

VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
    Flame   : BOOL;
END_VAR

VAR_OUTPUT
    Fan      : BOOL;
    Fuel     : BOOL;
    Ignition : BOOL;
END_VAR

VAR
    State    : INT;
    TimPurge : TON;
    TimIgn   : TON;
    Healthy  : BOOL;
END_VAR

VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN   : TIME := T#2s;
END_VAR

Healthy := EStop AND NOT StopPB;

TimPurge(IN := (State = 1), PT := PT_PURGE);
TimIgn  (IN := (State = 2), PT := PT_IGN);

IF NOT Healthy THEN
    State := 0;
ELSE
    CASE State OF

        0:
            IF StartPB THEN
                State := 1;
            END_IF;

        1:
            IF TimPurge.Q THEN
                State := 2;
            END_IF;

        2:
            IF TimIgn.Q THEN
                IF Flame THEN
                    State := 3;
                ELSE
                    State := 0;
                END_IF;
            END_IF;

        3:
            IF NOT Flame THEN
                State := 0;
            END_IF;

        ELSE
            State := 0;

    END_CASE;
END_IF;

Fan      := (State = 1) OR (State = 2) OR (State = 3);
Fuel     := Fan AND ((State = 2) OR (State = 3));
Ignition := Fan AND Fuel AND (State = 2);

END_PROGRAM

PROGRAM two_hand
VAR_INPUT
    LH : BOOL;
    RH : BOOL;
END_VAR
VAR_OUTPUT
    Actuator : BOOL;
END_VAR
VAR
    Armed : BOOL;
END_VAR

IF (NOT LH) AND (NOT RH) THEN
    Armed := TRUE;
ELSIF LH XOR RH THEN
    Armed := FALSE;
END_IF;

IF LH AND RH AND Armed THEN
    Actuator := TRUE;
ELSE
    Actuator := FALSE;
END_IF;

END_PROGRAM

PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop  : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead       : INT;
    PrevDemand : BOOL;
END_VAR

    IF NOT EStop THEN
        Pump1 := FALSE;
        Pump2 := FALSE;
    ELSE
        IF PrevDemand AND NOT Demand THEN
            IF Lead = 0 THEN
                Lead := 1;
            ELSE
                Lead := 0;
            END_IF;
        END_IF;

        IF Demand THEN
            IF Lead = 0 THEN
                Pump1 := TRUE;
                Pump2 := FALSE;
            ELSE
                Pump1 := FALSE;
                Pump2 := TRUE;
            END_IF;
        ELSE
            Pump1 := FALSE;
            Pump2 := FALSE;
        END_IF;
    END_IF;

    PrevDemand := Demand;

END_PROGRAM

PROGRAM gate
VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR

VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR

VAR
    State : INT;
END_VAR

MotorOpen := FALSE;
MotorClose := FALSE;

CASE State OF
    0:
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
        ELSIF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
            State := 2;
        END_IF;

    1:
        IF OpenLimit THEN
            State := 0;
        ELSE
            MotorOpen := TRUE;
        END_IF;

    2:
        IF CloseLimit THEN
            State := 0;
        ELSIF Obstruction THEN
            State := 0;
        ELSE
            MotorClose := TRUE;
        END_IF;

    ELSE
        State := 0;
END_CASE;

IF MotorOpen AND MotorClose THEN
    MotorOpen := FALSE;
    MotorClose := FALSE;
    State := 0;
END_IF;

END_PROGRAM

PROGRAM conveyor3

VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State  : INT;
    Timer1 : TON;
    Timer2 : TON;
END_VAR

VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

IF (StopPB = TRUE) OR (EStop = FALSE) THEN
    State  := 0;
    Timer1(IN := FALSE, PT := PT_SEQ);
    Timer2(IN := FALSE, PT := PT_SEQ);
ELSE
    CASE State OF
        0:
            Timer1(IN := FALSE, PT := PT_SEQ);
            Timer2(IN := FALSE, PT := PT_SEQ);
            IF StartPB = TRUE THEN
                State := 1;
            END_IF;

        1:
            Timer2(IN := FALSE, PT := PT_SEQ);
            Timer1(IN := TRUE, PT := PT_SEQ);
            IF Timer1.Q = TRUE THEN
                State := 2;
                Timer1(IN := FALSE, PT := PT_SEQ);
            END_IF;

        2:
            Timer1(IN := FALSE, PT := PT_SEQ);
            Timer2(IN := TRUE, PT := PT_SEQ);
            IF Timer2.Q = TRUE THEN
                State := 3;
                Timer2(IN := FALSE, PT := PT_SEQ);
            END_IF;

        3:
            Timer1(IN := FALSE, PT := PT_SEQ);
            Timer2(IN := FALSE, PT := PT_SEQ);

    ELSE
        State := 0;
        Timer1(IN := FALSE, PT := PT_SEQ);
        Timer2(IN := FALSE, PT := PT_SEQ);
    END_CASE;
END_IF;

C3 := (State = 1) OR (State = 2) OR (State = 3);
C2 := (State = 2) OR (State = 3);
C1 := (State = 3);

END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Done : BOOL;
END_VAR
VAR
    Count : INT;
    PrevTrigger : BOOL;
END_VAR
VAR CONSTANT
    N : INT := 3;
END_VAR

IF Reset THEN
    Count := 0;
    Done := FALSE;
    PrevTrigger := FALSE;
ELSE
    IF Trigger AND NOT PrevTrigger THEN
        IF Count < N THEN
            Count := Count + 1;
        END_IF;
    END_IF;
    PrevTrigger := Trigger;
    IF Count >= N THEN
        Done := TRUE;
    ELSE
        Done := FALSE;
    END_IF;
END_IF;

END_PROGRAM
